from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=2)
def process_row(A_row_i, A_row_k, k):
    pivot = A_row_k.get(k, 0.0)
    if pivot == 0.0:
        raise ValueError(f"Zero pivot encountered at index {k}")

    l_ik = A_row_i.get(k, 0.0) / pivot

    if l_ik != 0.0:
        for j, u_kj in A_row_k.items():
            if j >= k:
                current_val = A_row_i.get(j, 0.0)
                new_val = current_val - (l_ik * u_kj)

                if new_val != 0.0:
                    A_row_i[j] = new_val
                elif j in A_row_i:
                    del A_row_i[j]

    return A_row_i, l_ik

def main(A, N):
    A_rows = [{} for _ in range(N)]
    for item in A:
        A_rows[item['row']][item['column']] = float(item['value'])

    L_elements = []

    for k in range(N):
        A_row_k = A_rows[k]

        for i in range(k + 1, N):
            updated_row, l_ik = process_row(A_rows[i], A_row_k, k)

            A_rows[i] = updated_row
            L_elements.append((i, k, l_ik))

    A_rows = compss_wait_on(A_rows)

    L_futures = [elem[2] for elem in L_elements]
    L_values = compss_wait_on(L_futures)

    L_sparse = []
    U_sparse = []

    for i in range(N):
        L_sparse.append({'row': i, 'column': i, 'value': 1.0})

    for (i, k, _), val in zip(L_elements, L_values):
        if val != 0.0:
            L_sparse.append({'row': i, 'column': k, 'value': val})

    for i in range(N):
        for j, val in A_rows[i].items():
            if j >= i and val != 0.0:
                U_sparse.append({'row': i, 'column': j, 'value': val})

    return L_sparse, U_sparse
